<script lang="ts">
 import {fleetBuildPreview,fleetUpgradePreview,fleetLocation,type FleetBuildEffect,type FleetUpgradeEffect} from './fleet-preview';
 import type {PublicSetup} from './setup';
 let {game,position,effect: bonus,allowed,busy,respond,compact=false}:{game:PublicSetup;position:string;effect:FleetBuildEffect|FleetUpgradeEffect;allowed:boolean;busy:boolean;compact?:boolean;respond:(option:string,extra?:Record<string,unknown>)=>void}=$props();
 let shipIndex=$state(0);
 let selected=$state<string[]>([]),destination=$state('sol'),usePopulation=$state(false);
 $effect(()=>{const identity=JSON.stringify({cursor:game.discovery?.cursor,position,bonus});if(identity){selected=[];shipIndex=0;destination='sol';usePopulation=false;}});
 const build=$derived(bonus.kind==='ship'?fleetBuildPreview(game,position,bonus,bonus.location??destination,usePopulation):undefined);
 const upgrade=$derived(bonus.kind==='upgrade'?fleetUpgradePreview(game,position,bonus,selected):undefined);
 const locations=$derived(build?[build.power]:upgrade?.locations??[]);
 const selectedSummary=$derived(upgrade?.ships.filter(s=>s.selected).map(s=>`${s.label} ${s.level} → ${s.after}`).join(' · '));
 const powerSummary=$derived(locations.map(l=>{const p=l.powers.find(p=>p.position===position)!;return `${l.title} power ${p.before} → ${p.after}${l.controlChanges?` · control → ${game.players.find(p=>p.position===l.afterOwner)?.name??'uncontrolled'}${l.beforeOwner&&!l.beforePlaceholder?` · ${game.players.find(p=>p.position===l.beforeOwner)?.name}'s ${l.beforeTrack} disc returns`:''}`:''}`;}).join(' · '));
 function toggle(id:string,checked:boolean){selected=checked?[...selected,id]:selected.filter(s=>s!==id);}
</script>
<section class="fleet-effect" class:compact aria-label={build?'Ship construction decision':'Ship upgrade decision'}>
 <!-- svelte-ignore a11y_no_noninteractive_tabindex (Named bounded fleet region supports keyboard scrolling.) -->
 <div class="fleet-scroll" role="region" tabindex="0" aria-label="Ships and fleet power details"><p class="scroll-hint">{compact?"Browse owned ships · selection spends nothing":"Ships and power · scroll for all details"}</p>
 {#if build}
  <div class="conversion"><div class="source"><span class="cube source-cube" aria-hidden="true">{build.source.kind==='population'?'♟':'▣'}</span><div><small>Required cube</small><strong>{build.source.label}</strong><span>{build.source.before} → {build.source.after<0?'unavailable':build.source.after}</span></div></div><span class="arrow" aria-hidden="true">→</span><div class="built"><span class="cube" aria-hidden="true">{build.level}</span><div><small>New ship</small><strong>Level {build.level}</strong><span>{fleetLocation(game,build.destination)}</span></div></div></div>
  {#if !bonus.location}<fieldset><legend>Build location · Sol or your controlled shipyard</legend><div class="yard-options">{#each build.locations as id}<label class:selected={destination===id}><input type="radio" name="fleet-yard" value={id} bind:group={destination}/><span><strong>{fleetLocation(game,id)}</strong><small>{id==='sol'?'Home construction':'Your outpost controls this shipyard'}</small></span></label>{/each}</div></fieldset>{/if}
  {#if build.source.kind==='supply'&&build.source.before===0||build.canUsePopulation||usePopulation}<label class="fallback"><input type="checkbox" disabled={!allowed||busy||game.players.find(p=>p.position===position)!.population<1} bind:checked={usePopulation}/>Use 1 available Population instead of exhausted Supply</label>{/if}
 {:else if upgrade&&bonus.kind==='upgrade'}
  <fieldset><legend>{bonus.optional?'Up to ':''}{bonus.ships} distinct ship{bonus.ships===1?'':'s'} · +{bonus.levels} level{bonus.levels===1?'':'s'} · cap 4</legend><div class="ship-options">{#if compact&&upgrade.ships.length>1}<button class="ship-turn" aria-label="Previous ship" onclick={()=>shipIndex=(shipIndex+upgrade.ships.length-1)%upgrade.ships.length}>‹</button>{/if}{#each (compact?upgrade.ships.slice(Math.min(shipIndex,upgrade.ships.length-1),Math.min(shipIndex,upgrade.ships.length-1)+1):upgrade.ships) as ship}<label class:selected={ship.selected} class:unavailable={!ship.eligible}><input type="checkbox" aria-label={`Upgrade ${ship.label} at ${ship.title} · level ${ship.level} to ${Math.min(4,ship.level+bonus.levels)}`} checked={ship.selected} disabled={!allowed||busy||!ship.eligible||!ship.selected&&selected.length>=bonus.ships} onchange={e=>toggle(ship.id,e.currentTarget.checked)}/><span class="cube" aria-hidden="true">{ship.level}</span><span class="ship-name"><strong>{ship.label} · {ship.title}</strong><small>{ship.eligible?`Level ${ship.level} → ${ship.selected?ship.after:Math.min(4,ship.level+bonus.levels)}`:ship.level===4?'Level 4 · maximum':'Outside this bonus’s location'}</small></span></label>{/each}{#if compact&&upgrade.ships.length>1}<button class="ship-turn" aria-label="Next ship" onclick={()=>shipIndex=(shipIndex+1)%upgrade.ships.length}>›</button>{/if}</div>{#if compact&&upgrade.ships.length>1}<small class="ship-count" aria-live="polite">Ship {Math.min(shipIndex+1,upgrade.ships.length)} / {upgrade.ships.length} · {selected.length} selected</small>{/if}</fieldset>
 {/if}
 {#if locations.length&&!compact}<div class="power-register" aria-live="polite">{#each locations as location}<section aria-label={`${location.title} fleet power preview`}><strong>{location.title} · fleet power</strong><div class="power-rows">{#each location.powers as row}<span>{row.name}</span><span>{row.before} → <b>{row.after}</b></span>{/each}</div><small>{#if !location.controllable}This location cannot be controlled.{:else if location.controlChanges}Control would change to {game.players.find(p=>p.position===location.afterOwner)?.name??'uncontrolled'}. Resolve outposts and bonuses before continuing.{:else}Control stays {game.players.find(p=>p.position===location.afterOwner)?.name??'unclaimed'}; a tie preserves the incumbent.{/if}</small></section>{/each}</div>{/if}
 </div>
 <div class="fleet-commit"><p id="fleet-decision-reason">{build?.reason??upgrade?.reason??''}{#if !(build?.reason??upgrade?.reason)}{build?`Convert ${build.source.label} into a level-${build.level} ship.`:selected.length?`${selectedSummary} · ${powerSummary}. No cube is spent.`:'No ships selected; decline the optional upgrade.'}{/if}</p><button class="primary" aria-describedby="fleet-decision-reason" disabled={!allowed||busy||!!(build?.reason??upgrade?.reason)} onclick={()=>build?respond('build',{destination:build.destination,...(usePopulation?{usePopulation:true}:{})}):respond('upgrade',{ships:selected})}>{build?`Build level${build.level} ship`:`Commit ship upgrade${bonus.kind==='upgrade'&&bonus.optional&&!selected.length?' · pass':''}`}</button>{#if build?.source.kind==='supply'&&build.source.before===0||build?.canUsePopulation||build&&usePopulation}<button disabled={!allowed||busy} onclick={()=>respond('pass')}>Pass on exhausted Supply bonus</button>{/if}</div>
</section>
<style>
.fleet-effect{display:flex;flex-direction:column;gap:8px;min-height:0;container-type:inline-size;color:#efe6cb}.conversion{display:grid;grid-template-columns:1fr 28px 1fr;align-items:center;gap:8px;padding:16px;background:linear-gradient(125deg,#f2e4bd,#c9b78d);border:1px solid #bba26a;border-radius:8px;color:#253b37;box-shadow:inset 0 0 0 3px #fff1ca55,0 4px #705c3e}.source,.built{display:flex;align-items:center;gap:13px}.conversion strong,.conversion small,.conversion span:not(.cube){display:block}.conversion small{font-size:11px;text-transform:uppercase;letter-spacing:.06em}.conversion strong{font:600 21px 'Cormorant Garamond',serif;margin:4px 0}.conversion span{font-size:13px}.conversion .arrow{font-size:28px;text-align:center}.cube{display:inline-grid;place-items:center;flex:none;width:45px;height:45px;border:1px solid #7ed8d0;border-radius:7px;background:linear-gradient(130deg,#57bdb9,#1b615f);box-shadow:inset -5px -5px #133f4b66,inset 3px 3px #a5f4e655,2px 4px 0 #173e42;color:#fff5d3;font:600 27px 'Cormorant Garamond',serif}.source-cube{background:linear-gradient(130deg,#e5d8b7,#b7a17a);border-color:#957b4e;color:#263e38;box-shadow:inset -5px -5px #826d4d44,2px 4px #756349}fieldset{min-width:0;border:1px solid #b29b65;border-radius:8px;padding:12px;margin:0}legend{font-size:13px;line-height:1.5;padding:0 6px}.ship-options,.yard-options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.ship-options label,.yard-options label{display:flex;gap:10px;align-items:center;min-height:70px;padding:10px;border:1px solid #a08c5f88;border-radius:7px;background:linear-gradient(130deg,#2d4545,#152c34);cursor:pointer}.selected{border-color:#76e5d4!important;background:linear-gradient(130deg,#315a55,#194145)!important;box-shadow:inset 0 0 0 1px #76e5d466}.ship-name{min-width:0}strong,small{display:block}.ship-name strong,.yard-options strong{font-size:14px;line-height:1.3}.ship-name small,.yard-options small{font-size:12px;margin-top:5px;color:#d3cfb6}.unavailable{opacity:.55}.power-register{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:10px}.power-register section{padding:12px;border:1px solid #a9946355;border-radius:7px;background:#0e252c}.power-register strong{font-size:14px;color:#f0e1b9}.power-rows{display:grid;grid-template-columns:1fr auto;gap:4px 15px;font-size:13px;padding:8px 0}.power-register small{font-size:12px;line-height:1.4;color:#d1d0b6}.fleet-commit{display:flex;flex-wrap:wrap;gap:10px;align-items:center;padding:13px;border:1px solid #ab9666;border-radius:8px;background:#1b363b}.fleet-commit p{margin:0;flex:1 1 180px;font-size:13px;line-height:1.4}button{min-height:44px;padding:10px 14px;border:1px solid #baa065;border-radius:7px;background:linear-gradient(130deg,#354c48,#152f37);color:#eee5cb;font:14px 'Atkinson Hyperlegible',sans-serif;cursor:pointer}.primary{background:#15575a}button:disabled{opacity:.55;cursor:default}input{color-scheme:dark;width:44px;height:44px;flex:none;accent-color:#5bcbbb}label{min-height:44px}.fallback{display:flex;align-items:center;gap:10px;font-size:13px}input:focus-visible,button:focus-visible{outline:3px solid #71eee7;outline-offset:3px}.ship-options label:has(input:focus-visible),.yard-options label:has(input:focus-visible){outline:3px solid #71eee7;outline-offset:3px}@container(max-width:500px){.ship-options,.yard-options{grid-template-columns:1fr}.conversion{padding:12px}.source,.built{gap:8px}.conversion strong{font-size:19px}.cube{width:40px;height:40px}.ship-options label{min-height:64px}}@container(max-width:300px){.conversion{grid-template-columns:1fr}.conversion .arrow{transform:rotate(90deg)}.fleet-commit button{width:100%}}

.fleet-scroll{flex:1;min-height:0;overflow:auto;padding:3px 4px 8px;display:grid;gap:12px;align-content:start;scrollbar-color:#c4aa70 #112b31;scrollbar-width:thin}.scroll-hint{font-size:11px;color:#cbd1bb;margin:0}.fleet-commit{flex:none}.fleet-scroll:focus-visible{outline:3px solid #71eee7;outline-offset:-3px}

.compact .ship-options{grid-template-columns:1fr}.compact fieldset{padding:6px 8px}.compact legend{font-size:12px}.compact .ship-options label{padding:6px;min-height:60px;gap:7px}.compact .ship-name strong{font-size:13px}.compact .ship-name small{font-size:12px}.compact .ship-options:has(.ship-turn){grid-template-columns:44px minmax(0,1fr) 44px;align-items:center;gap:5px}.ship-turn{width:44px;height:44px;padding:0;font-size:26px}.ship-count{text-align:center;font-size:11px;margin-top:5px}.compact .fleet-scroll{gap:6px;padding:2px 3px 6px}.compact .fleet-commit{display:grid;grid-template-columns:minmax(0,1fr) auto;padding:8px;gap:8px}.compact .fleet-commit p{font-size:12px;flex-basis:100%}.compact .fleet-commit button{min-height:44px;padding:7px 10px;font-size:12px}.compact .scroll-hint{display:none}.compact .fleet-scroll{gap:0}
</style>
